#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int stack[100000];
    int top = 0;
    long long sum = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        if (x == 0) {
            if (top > 0) {
                top--;
                sum -= stack[top];
            }
        } else {
            stack[top++] = x;
            sum += x;
        }
    }

    printf("%lld\n", sum);
    return 0;
}
